#!/bin/bash
DB="docker exec 1Panel-postgresql-pIe0 psql -U strapi -d strapi -v ON_ERROR_STOP=0"
echo "===== A. sso_invite_codes 归属（sso_user 视角）====="
$DB -c "SELECT c.id, c.code, c.app_code, c.invite_type, c.use_count, c.max_uses, c.is_active, c.created_at, lnk.sso_user_id AS creator_sso FROM sso_invite_codes c LEFT JOIN sso_invite_codes_creator_lnk lnk ON lnk.sso_invite_code_id=c.id ORDER BY c.id;"
echo ""
echo "===== B. sso_referral_relations 分销关系 ====="
$DB -c "SELECT r.id, r.level, r.channel_code, r.created_at, vi.sso_user_id AS inviter, ie.sso_user_id AS invitee, ic.sso_invite_code_id, ci.code FROM sso_referral_relations r LEFT JOIN sso_referral_relations_inviter_lnk vi ON vi.sso_referral_relation_id=r.id LEFT JOIN sso_referral_relations_invitee_lnk ie ON ie.sso_referral_relation_id=r.id LEFT JOIN sso_referral_relations_invite_code_lnk ic ON ic.sso_referral_relation_id=r.id LEFT JOIN sso_invite_codes ci ON ci.id=ic.sso_invite_code_id ORDER BY r.id;"
echo ""
echo "===== C. sso_invite_usages 邀请码使用 ====="
$DB -c "SELECT u.id, u.app_code, u.channel_code, u.used_at, ul.sso_user_id AS user_sso, ci.code AS used_code FROM sso_invite_usages u LEFT JOIN sso_invite_usages_user_lnk ul ON ul.sso_invite_usage_id=u.id LEFT JOIN sso_invite_usages_invite_code_lnk ic ON ic.sso_invite_usage_id=u.id LEFT JOIN sso_invite_codes ci ON ci.id=ic.sso_invite_code_id ORDER BY u.id;"
echo ""
echo "===== D. activity_referral_rewards 推荐奖励 ====="
$DB -c "SELECT a.id, a.points, a.source_invite_code, a.issued_at, vi.user_id AS inviter, ie.user_id AS invitee FROM activity_referral_rewards a LEFT JOIN activity_referral_rewards_inviter_lnk vi ON vi.activity_referral_reward_id=a.id LEFT JOIN activity_referral_rewards_invitee_lnk ie ON ie.activity_referral_reward_id=a.id ORDER BY a.id;"
echo ""
echo "===== E. zhao_point_records 分享/邀请类积分 ====="
$DB -c "SELECT r.id, r.action, r.type, r.points, r.source, r.remark, r.created_at, lnk.user_id FROM zhao_point_records r LEFT JOIN zhao_point_records_user_lnk lnk ON lnk.point_record_id=r.id WHERE r.action ILIKE '%share%' OR r.action ILIKE '%invite%' ORDER BY r.id DESC LIMIT 30;"
echo ""
echo "===== F. zhao_point_share_visits 分享访问归因 ====="
$DB -c "SELECT v.target_type, v.target_id, count(*) FROM zhao_point_share_visits v GROUP BY v.target_type, v.target_id;"
$DB -c "SELECT v.id, v.target_type, v.target_id, v.created_at, lnk.user_id AS inviter FROM zhao_point_share_visits v LEFT JOIN zhao_point_share_visits_inviter_lnk lnk ON lnk.activity_share_visit_id=v.id ORDER BY v.id DESC LIMIT 15;"
echo ""
echo "===== G. 分享/任务相关规则（点规则表，走默认兜底则无记录）====="
$DB -c "SELECT id, action, points, enabled, limit_per_day, is_one_time, link_type, link_target_id FROM zhao_point_rules WHERE action ILIKE '%share%';"